use super::*;

/// What an hour has to earn.
///
/// The offer assessment is printed BELOW the ladder rather than beside it, because the two answer
/// different questions: what you must charge, and whether a specific number on the table can get
/// there at all. Merging them reads as one recommendation and it is two facts.
pub fn render_rate(f: &rate::RateFloor, offers: &[rate::OfferVerdict], read_notes: &[String]) -> String {
    let mut out = String::new();
    let m = |x: i64| crate::money::format_minor(x);
    out.push_str(&format!("{}\n\n", rate::summarise(f)));
    out.push_str("  tier         needs/month     must bill      hourly     day rate\n");
    for t in &f.tiers {
        out.push_str(&format!(
            "  {:<12}{:>12}{:>14}{:>12}{:>13}\n",
            t.tier.label(),
            m(t.monthly_need.minor),
            m(t.must_bill_monthly.minor),
            m(t.hourly.minor),
            m(t.day_rate.minor)
        ));
    }

    if !offers.is_empty() {
        let offered = offers[0].offered;
        out.push_str(&format!("\n  at {} an hour:\n", m(offered.minor)));
        for o in offers {
            out.push_str(&format!(
                "    {:<12}{:>6.0}h of {:.0}h  {}\n",
                o.tier.label(),
                o.hours_needed,
                o.hours_available,
                if o.reachable { "reachable" } else { "OUT OF REACH at any hours" }
            ));
        }
        // The one that matters is whether it reaches CURRENT — the line below which new damage
        // starts. Printed as prose because it is the sentence somebody needs in a negotiation.
        if let Some(c) = offers.iter().find(|o| o.tier == crate::viable::Tier::Current) {
            out.push_str(&format!("\n  {}\n", c.why));
        }
    }

    out.push_str("\nWhat this is standing on:\n");
    for a in &f.assumptions {
        out.push_str(&format!("  · {a}\n"));
    }
    for w in &f.warnings {
        out.push_str(&format!("  · {w}\n"));
    }
    for n in read_notes {
        out.push_str(&format!("  · {n}\n"));
    }
    out
}
